import { ThresholdColor } from '../../../core/types/threshold-types.js';
/** Extension interface for the TableState when useThreshold plugin is used. */
export interface UseThresholdsState {
    /**
     * If set to `true`, the current table configuration supports cell and row thresholds.
     *
     * @defaultValue false
     */
    thresholdsEnabled?: boolean;
}
/** Extension interface for type `Row` required for using the `useThreshold` plugin hook. */
export interface UseHighlightRowProps {
    highlightColor?: ThresholdColor;
}
/** Extension interface for type `Cell` required for using the `useThreshold` plugin hook. */
export interface UseHighlightCellProps {
    highlightColor?: ThresholdColor;
}
